import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第十二卦 否 地天否 乾上坤下","description":"周易 - 第十二卦 否 地天否 乾上坤下","frontmatter":{"title":"第十二卦 否 地天否 乾上坤下","description":"周易 - 第十二卦 否 地天否 乾上坤下"},"headers":[],"relativePath":"classics/zhouyi/013.md","filePath":"classics/zhouyi/013.md"}'),l={name:"classics/zhouyi/013.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="否" tabindex="-1">否 <a class="header-anchor" href="#否" aria-label="Permalink to “否”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>否之匪人，不利君子貞，大往小來。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>否之匪人，不利君子貞。大往小來，則是天地不交，而萬物不通也；上下不交，而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子。小人道長，君子道消也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>天地不交，否；君子以儉德闢難，不可榮以祿。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>拔茅茹，以其夤，貞吉 亨。象曰：拔茅貞吉，志在君也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>包承。小人吉，大人否亨。象曰：大人否亨，不亂群也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>包羞。象曰：包羞，位不當也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>有命無咎，疇離祉。象曰：有命無咎，志行也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>休否，大人吉。其亡其亡，繫於苞桑。象曰：大人之吉，位正當也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>傾否，先否後喜。象曰：否終則傾，何可長也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
